const properties = $('XML5').first().json.root.property;
const lista = Array.isArray(properties) ? properties : [properties];

// Mapeo type inglés → español
const typeMap = {
  'flat': 'Piso',
  'apartment': 'Apartamento',
  'chalet': 'Chalet',
  'semi-detached house': 'Adosado',
  'duplex': 'Dúplex',
  'commercial': 'Local comercial',
  'house': 'Casa',
  'villa': 'Villa',
  'penthouse': 'Ático',
  'studio': 'Estudio',
  'land': 'Terreno',
  'townhouse': 'Casa adosada',
  'bungalow': 'Bungalow',
  'country house': 'Casa de campo',
  'garage': 'Garaje',
  'storage': 'Trastero',
  'office': 'Oficina',
  'building': 'Edificio',
};

// Mapeo features inglés → español
const featuresMap = {
  'bathroom': 'baño',
  'bathrooms': 'baños',
  'bedroom': 'habitación',
  'bedrooms': 'habitaciones',
  'city center': 'centro ciudad',
  'school': 'colegio cercano',
  'pharmacy': 'farmacia cercana',
  'green areas': 'zonas verdes',
  'outdoor building': 'edificio exterior',
  'floor': 'planta',
  'gross area': 'superficie bruta',
  'net area': 'superficie neta',
  'construction ended': 'año construcción',
  'pool': 'piscina',
  'garden': 'jardín',
  'terrace': 'terraza',
  'balcony': 'balcón',
  'garage': 'garaje',
  'parking': 'parking',
  'lift': 'ascensor',
  'elevator': 'ascensor',
  'air conditioning': 'aire acondicionado',
  'central heating': 'calefacción central',
  'heating': 'calefacción',
  'furnished': 'amueblado',
  'unfurnished': 'sin amueblar',
  'sea view': 'vistas al mar',
  'mountain view': 'vistas a la montaña',
  'storage room': 'trastero',
  'fitted wardrobes': 'armarios empotrados',
  'security door': 'puerta blindada',
  'double glazing': 'doble acristalamiento',
  'near beach': 'cerca de la playa',
  'near shops': 'cerca de comercios',
  'near transport': 'cerca de transporte',
  'communal pool': 'piscina comunitaria',
  'private pool': 'piscina privada',
  'utility room': 'lavadero',
  'reception': 'recepción',
  'alarm': 'alarma',
  'intercom': 'portero automático',
};

function traducirFeature(feat) {
  const f = feat.toString().trim();
  const lower = f.toLowerCase();

  if (featuresMap[lower]) return featuresMap[lower];

  const match = f.match(/^([\d.]+)\s+(.+)$/);
  if (match) {
    const num = match[1];
    const palabra = match[2].toLowerCase();
    if (featuresMap[palabra]) return `${featuresMap[palabra]} ${num}`;
    if (palabra === 'gross area') return `superficie bruta ${num} m²`;
    if (palabra === 'net area') return `superficie neta ${num} m²`;
  }

  const matchConst = f.match(/^(\d{4})-\d{2}-\d{2}\s+construction ended$/i);
  if (matchConst) return `año construcción ${matchConst[1]}`;

  return f;
}

return lista.map(p => {
  // Traducir tipo de inmueble
  const tipoOriginal = (p.type || '').toString().trim();
  const tipoTraducido = typeMap[tipoOriginal.toLowerCase()] || tipoOriginal;

  // Extraer y traducir features
  let features = [];
  if (p.features?.feature) {
    const raw = p.features.feature;
    features = (Array.isArray(raw) ? raw : [raw])
      .map(f => traducirFeature(f))
      .filter(f => f);
  }

  return {
    json: {
      ref: (p.ref || '').toString(),
      precio: parseFloat(p.price) || 0,
      tipo_transaccion: (p.price_freq || '').toString().toLowerCase() === 'sale' ? 'venta' : 'alquiler',
      tipo_inmueble: tipoTraducido,
      municipio: (p.town || '').toString(),
      zona: (p.location_detail || '').toString(),
      habitaciones: parseInt(p.beds) || 0,
      banos: parseInt(p.baths) || 0,
      superficie: (p.surface_area?.built || '').toString(),
      caracteristicas: features.join(', '),
      descripcion: (p.desc?.es || '').toString().substring(0, 500),
      imagen: (Array.isArray(p.images?.image)
        ? p.images.image[0]?.url
        : p.images?.image?.url) || '',
      latitud: (p.location?.latitude || '').toString(),
      longitud: (p.location?.longitude || '').toString(),
    }
  };
});

// Guardafuegos: si el feed viene vacio o a medias, se aborta ANTES de
// vaciar la hoja, para no dejar a Sara sin cartera que ofrecer.
const props = $('XML5').first().json?.root?.property;
const lista = Array.isArray(props) ? props : (props ? [props] : []);
if (lista.length < 5) {
  throw new Error(`El feed ha devuelto ${lista.length} inmuebles. No se vacia la hoja.`);
}
return [{ json: { total: lista.length } }];
